INSERT INTO quality.tb_word (word_id,word_nm,word_eng_abrv_nm,word_eng_nm,word_desc,word_clsf_yn,domain_clsf_nm,comm_stnd_yn,aprv_yn,cret_dt,cret_user_id,use_yn) VALUES ('iqJlOgQcM0RkPZFXA2Wuq4','TLS','TLS','TRANSPORT LAYER SECURITY','현재 널리 사용되고 있는 SSL(Security Sockets Layer)을 대체할 차세대 안전 통신 규약. SSL에 비해 강력한 암호화를 실현할 수 있고 폭이 넓은 망의 통신 규약에 대응되어 있는 점에서 주목을 끌고 있다. 암호화에는 3개의 다른 데이터 암호화 표준(DES) 키를 사용한 트리플(triple) DES 암호화 기술이 응용되고 있다.
